#!/usr/bin/env python3\n\"\"\"\nMódulo de Reconhecimento Facial - Áquila Pro\nPasso 5: Implementar face_recognition.py com modelos pré-treinados\n\nDependências:\n- face_recognition\n- numpy\n- opencv-python\n- pillow\n\nInstalação:\n  pip install face_recognition numpy opencv-python pillow\n\"\"\"\n\nimport face_recognition\nimport numpy as np\nimport cv2\nimport os\nimport json\nfrom pathlib import Path\nfrom typing import List, Dict, Tuple, Optional\nimport logging\nfrom datetime import datetime\n\n# Configurar logging\nlogging.basicConfig(\n    level=logging.INFO,\n    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'\n)\nlogger = logging.getLogger('FaceRecognition')\n\n\nclass FaceRecognitionModule:\n    \"\"\"\n    Módulo de reconhecimento facial usando face_recognition\n    Extrai embeddings de faces e compara com banco de dados\n    \"\"\"\n\n    def __init__(self, model_type: str = 'hog', tolerance: float = 0.6):\n        \"\"\"\n        Inicializar módulo de reconhecimento facial\n\n        Args:\n            model_type: 'hog' (rápido) ou 'cnn' (preciso, requer GPU)\n            tolerance: Limiar de similaridade (0.0-1.0, menor = mais restritivo)\n        \"\"\"\n        self.model_type = model_type\n        self.tolerance = tolerance\n        self.known_encodings: Dict[str, List[np.ndarray]] = {}\n        self.known_names: List[str] = []\n        self.encoding_cache: Dict[str, np.ndarray] = {}\n        logger.info(f'FaceRecognitionModule inicializado com modelo: {model_type}')\n\n    def extract_embedding(self, image_path: str) -> Optional[np.ndarray]:\n        \"\"\"\n        Extrair embedding de uma imagem\n\n        Args:\n            image_path: Caminho da imagem\n\n        Returns:\n            Array numpy com embedding (128D) ou None se nenhuma face encontrada\n        \"\"\"\n        try:\n            # Carregar imagem\n            image = face_recognition.load_image_file(image_path)\n\n            # Encontrar faces\n            face_locations = face_recognition.face_locations(\n                image, model=self.model_type\n            )\n\n            if not face_locations:\n                logger.warning(f'Nenhuma face encontrada em {image_path}')\n                return None\n\n            # Extrair embedding da primeira face\n            face_encodings = face_recognition.face_encodings(\n                image, face_locations\n            )\n\n            if face_encodings:\n                embedding = face_encodings[0]\n                logger.debug(f'Embedding extraído de {image_path}')\n                return embedding\n            else:\n                logger.warning(f'Não foi possível extrair embedding de {image_path}')\n                return None\n\n        except Exception as e:\n            logger.error(f'Erro ao extrair embedding: {str(e)}')\n            return None\n\n    def extract_embeddings_batch(self, image_paths: List[str]) -> Dict[str, np.ndarray]:\n        \"\"\"\n        Extrair embeddings de múltiplas imagens\n\n        Args:\n            image_paths: Lista de caminhos de imagens\n\n        Returns:\n            Dicionário {caminho: embedding}\n        \"\"\"\n        embeddings = {}\n\n        for image_path in image_paths:\n            embedding = self.extract_embedding(image_path)\n            if embedding is not None:\n                embeddings[image_path] = embedding\n\n        logger.info(f'Extraídos {len(embeddings)}/{len(image_paths)} embeddings')\n        return embeddings\n\n    def train_student(self, student_id: str, image_paths: List[str]) -> bool:\n        \"\"\"\n        Treinar modelo com fotos de um aluno\n\n        Args:\n            student_id: ID único do aluno\n            image_paths: Lista de caminhos de fotos do aluno\n\n        Returns:\n            True se treinamento bem-sucedido\n        \"\"\"\n        try:\n            logger.info(f'Treinando aluno {student_id} com {len(image_paths)} fotos')\n\n            embeddings = []\n\n            for image_path in image_paths:\n                embedding = self.extract_embedding(image_path)\n                if embedding is not None:\n                    embeddings.append(embedding)\n\n            if not embeddings:\n                logger.warning(f'Nenhum embedding extraído para aluno {student_id}')\n                return False\n\n            # Armazenar embeddings\n            self.known_encodings[student_id] = embeddings\n            self.known_names.append(student_id)\n\n            logger.info(f'Aluno {student_id} treinado com {len(embeddings)} embeddings')\n            return True\n\n        except Exception as e:\n            logger.error(f'Erro ao treinar aluno: {str(e)}')\n            return False\n\n    def recognize_face(self, image_path: str) -> Optional[Dict]:\n        \"\"\"\n        Reconhecer face em uma imagem\n\n        Args:\n            image_path: Caminho da imagem\n\n        Returns:\n            Dicionário com {student_id, confidence} ou None\n        \"\"\"\n        try:\n            # Extrair embedding da imagem\n            test_embedding = self.extract_embedding(image_path)\n            if test_embedding is None:\n                return None\n\n            # Comparar com embeddings conhecidos\n            best_match = None\n            best_distance = float('inf')\n\n            for student_id, encodings in self.known_encodings.items():\n                # Calcular distância com cada embedding do aluno\n                distances = face_recognition.face_distance(encodings, test_embedding)\n                min_distance = np.min(distances)\n\n                if min_distance < best_distance:\n                    best_distance = min_distance\n                    best_match = student_id\n\n            # Verificar se distância está dentro do limiar\n            if best_distance <= self.tolerance:\n                confidence = 1.0 - best_distance  # Converter para confiança\n                logger.info(\n                    f'Face reconhecida: {best_match} (confiança: {confidence:.2f})'\n                )\n                return {\n                    'student_id': best_match,\n                    'confidence': float(confidence),\n                    'distance': float(best_distance),\n                }\n            else:\n                logger.info(f'Face não reconhecida (distância: {best_distance:.2f})')\n                return None\n\n        except Exception as e:\n            logger.error(f'Erro ao reconhecer face: {str(e)}')\n            return None\n\n    def recognize_faces_in_frame(self, frame: np.ndarray) -> List[Dict]:\n        \"\"\"\n        Reconhecer múltiplas faces em um frame de vídeo\n\n        Args:\n            frame: Frame de vídeo (numpy array)\n\n        Returns:\n            Lista de dicionários com detecções\n        \"\"\"\n        try:\n            # Redimensionar frame para processamento mais rápido\n            small_frame = cv2.resize(frame, (0, 0), fx=0.25, fy=0.25)\n            rgb_small_frame = cv2.cvtColor(small_frame, cv2.COLOR_BGR2RGB)\n\n            # Encontrar faces\n            face_locations = face_recognition.face_locations(\n                rgb_small_frame, model=self.model_type\n            )\n\n            if not face_locations:\n                return []\n\n            # Extrair embeddings\n            face_encodings = face_recognition.face_encodings(\n                rgb_small_frame, face_locations\n            )\n\n            results = []\n\n            for face_encoding, face_location in zip(face_encodings, face_locations):\n                # Comparar com embeddings conhecidos\n                best_match = None\n                best_distance = float('inf')\n\n                for student_id, encodings in self.known_encodings.items():\n                    distances = face_recognition.face_distance(\n                        encodings, face_encoding\n                    )\n                    min_distance = np.min(distances)\n\n                    if min_distance < best_distance:\n                        best_distance = min_distance\n                        best_match = student_id\n\n                # Verificar limiar\n                if best_distance <= self.tolerance:\n                    confidence = 1.0 - best_distance\n                    # Converter coordenadas de volta ao tamanho original\n                    top, right, bottom, left = face_location\n                    top *= 4\n                    right *= 4\n                    bottom *= 4\n                    left *= 4\n\n                    results.append({\n                        'student_id': best_match,\n                        'confidence': float(confidence),\n                        'location': {\n                            'top': top,\n                            'right': right,\n                            'bottom': bottom,\n                            'left': left,\n                        },\n                    })\n\n            return results\n\n        except Exception as e:\n            logger.error(f'Erro ao reconhecer faces no frame: {str(e)}')\n            return []\n\n    def calculate_similarity(self, embedding1: np.ndarray, embedding2: np.ndarray) -> float:\n        \"\"\"\n        Calcular similaridade entre dois embeddings\n\n        Args:\n            embedding1: Primeiro embedding\n            embedding2: Segundo embedding\n\n        Returns:\n            Similaridade (0.0-1.0)\n        \"\"\"\n        distance = np.linalg.norm(embedding1 - embedding2)\n        similarity = 1.0 - distance\n        return float(np.clip(similarity, 0.0, 1.0))\n\n    def save_model(self, filepath: str) -> bool:\n        \"\"\"\n        Salvar modelo treinado em arquivo JSON\n\n        Args:\n            filepath: Caminho do arquivo\n\n        Returns:\n            True se salvo com sucesso\n        \"\"\"\n        try:\n            # Converter embeddings para listas (numpy arrays não são serializáveis)\n            data = {\n                'known_encodings': {\n                    student_id: [enc.tolist() for enc in encodings]\n                    for student_id, encodings in self.known_encodings.items()\n                },\n                'known_names': self.known_names,\n                'tolerance': self.tolerance,\n                'model_type': self.model_type,\n                'timestamp': datetime.now().isoformat(),\n            }\n\n            with open(filepath, 'w') as f:\n                json.dump(data, f, indent=2)\n\n            logger.info(f'Modelo salvo em {filepath}')\n            return True\n\n        except Exception as e:\n            logger.error(f'Erro ao salvar modelo: {str(e)}')\n            return False\n\n    def load_model(self, filepath: str) -> bool:\n        \"\"\"\n        Carregar modelo treinado de arquivo JSON\n\n        Args:\n            filepath: Caminho do arquivo\n\n        Returns:\n            True se carregado com sucesso\n        \"\"\"\n        try:\n            with open(filepath, 'r') as f:\n                data = json.load(f)\n\n            # Converter listas de volta para numpy arrays\n            self.known_encodings = {\n                student_id: [np.array(enc) for enc in encodings]\n                for student_id, encodings in data['known_encodings'].items()\n            }\n            self.known_names = data['known_names']\n            self.tolerance = data.get('tolerance', 0.6)\n            self.model_type = data.get('model_type', 'hog')\n\n            logger.info(f'Modelo carregado de {filepath}')\n            return True\n\n        except Exception as e:\n            logger.error(f'Erro ao carregar modelo: {str(e)}')\n            return False\n\n    def get_statistics(self) -> Dict:\n        \"\"\"\n        Obter estatísticas do modelo\n\n        Returns:\n            Dicionário com estatísticas\n        \"\"\"\n        total_embeddings = sum(\n            len(encodings) for encodings in self.known_encodings.values()\n        )\n\n        return {\n            'total_students': len(self.known_encodings),\n            'total_embeddings': total_embeddings,\n            'model_type': self.model_type,\n            'tolerance': self.tolerance,\n            'cache_size': len(self.encoding_cache),\n        }\n\n\nif __name__ == '__main__':\n    # Exemplo de uso\n    print('Face Recognition Module - Teste')\n\n    # Inicializar módulo\n    fr = FaceRecognitionModule(model_type='hog', tolerance=0.6)\n\n    # Treinar aluno (exemplo)\n    # fr.train_student('student-001', ['photo1.jpg', 'photo2.jpg', 'photo3.jpg'])\n\n    # Reconhecer face\n    # result = fr.recognize_face('test_photo.jpg')\n    # print(result)\n\n    # Salvar modelo\n    # fr.save_model('model.json')\n\n    # Carregar modelo\n    # fr.load_model('model.json')\n\n    print('Módulo carregado com sucesso!')\n
